{
  "name": "点图形标注组件",
  "name_en": "Point Graphic Annotation Component",
  "manufacturer": "Nion",
  "description": "用于科学成像与实验数据界面的点状图形标注对象。这是一个非物理软件组件，源自 Nion Swift 图形模型，用于在图像或数据视图中表示单点标记，并支持位置管理、命中测试、拖拽编辑、微调以及基于 MIME 的序列化/复制交换，常用于交互式选点、特征标注和区域定义。",
  "description_en": "A point-style graphical annotation object for scientific imaging and experimental data interfaces. This is a non-physical software component from the Nion Swift graphics model, used to represent a single point marker in an image or data view. It supports position management, hit testing, drag editing, nudging, and MIME-based serialization or copy/transfer, commonly for interactive point selection, feature marking, and region definition.",
  "actions": [
    {
      "action_name": "auto-position",
      "description": "获取或设置点图形的位置。",
      "description_en": "Get or set the point graphic position."
    },
    {
      "action_name": "auto-reset_position",
      "description": "重置点图形到默认位置。",
      "description_en": "Reset the point graphic to its default position."
    },
    {
      "action_name": "auto-mime_data_dict",
      "description": "导出点图形的 MIME 数据字典，用于复制、拖放或状态交换。",
      "description_en": "Export a MIME data dictionary for the point graphic for copy, drag-and-drop, or state transfer."
    },
    {
      "action_name": "auto-read_from_mime_data",
      "description": "从 MIME 数据字典读取并恢复点图形状态。",
      "description_en": "Read and restore the point graphic state from a MIME data dictionary."
    },
    {
      "action_name": "auto-test",
      "description": "测试给定坐标是否命中点图形或其标签，用于界面交互判定。",
      "description_en": "Test whether a given coordinate hits the point graphic or its label for UI interaction."
    },
    {
      "action_name": "auto-begin_drag",
      "description": "开始点图形的拖拽交互。",
      "description_en": "Begin drag interaction for the point graphic."
    },
    {
      "action_name": "auto-end_drag",
      "description": "结束点图形的拖拽交互。",
      "description_en": "End drag interaction for the point graphic."
    },
    {
      "action_name": "auto-adjust_part",
      "description": "根据坐标映射、拖拽部位和修饰键调整点图形。",
      "description_en": "Adjust the point graphic based on coordinate mapping, dragged part, and modifier keys."
    },
    {
      "action_name": "auto-nudge",
      "description": "按给定增量微移点图形。",
      "description_en": "Nudge the point graphic by a given delta."
    }
  ],
  "tag_hints": [
    "graphical annotation",
    "point ROI",
    "interactive image overlay",
    "hit testing",
    "drag editing",
    "MIME serialization",
    "Nion Swift"
  ]
}

